SELECT jsonb_build_object('checked_at',clock_timestamp(),'read_only',current_setting('default_transaction_read_only'),
 'vocabulary',jsonb_build_object('rows',(SELECT count(*) FROM public."Feature_Vocabulary"),
 'stock',(SELECT count(*) FROM public."Feature_Vocabulary" WHERE scope='stock'),
 'index',(SELECT count(*) FROM public."Feature_Vocabulary" WHERE scope='index'),
 'feature04',(SELECT count(*) FROM public."Feature_Vocabulary" WHERE feature_number=4),
 'unverified',(SELECT count(*) FROM public."Feature_Vocabulary" WHERE review_status<>'VERIFIED'),
 'missing_physical_columns',(SELECT count(*) FROM public."Feature_Vocabulary" v LEFT JOIN information_schema.columns c ON c.table_schema=v.source_schema AND c.table_name=v.source_table AND c.column_name=v.column_name WHERE c.column_name IS NULL),
 'payload',(SELECT jsonb_agg(to_jsonb(v) ORDER BY source_table,display_order) FROM public."Feature_Vocabulary" v)),
 'feature05_removed_columns',(SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='Feature_05_Foreign_Domestic_Broker_Detail_INDEX' AND column_name IN ('frequency_source_rows','buy_freq_known_rows','sell_freq_known_rows','buy_freq_missing_rows','sell_freq_missing_rows')),
 'feature06_coverage_columns',(SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='Feature_06_Foreign_Domestic_INDEX' AND column_name IN ('frequency_source_rows','buy_freq_known_rows','sell_freq_known_rows','buy_freq_missing_rows','sell_freq_missing_rows')),
 'feature03_hhi_nonnull',(SELECT count(*) FROM public."Feature_03_Stock_Broker_Daily_INDEX" WHERE ticker='IHSG' AND broker_concentration_hhi IS NOT NULL),
 'feature04_wrong_asset_type',(SELECT count(*) FROM public."Feature_04_Technical_Indicator_INDEX" WHERE ticker='IHSG' AND asset_type<>'index'),
 'feature04_close_mismatches',(SELECT count(*) FROM public."Feature_04_Technical_Indicator_INDEX" f LEFT JOIN public."Price_Stock_Indonesia_IDX" p ON p.ticker=f.ticker AND p.date=f.trade_date AND p.timeframe=f.timeframe WHERE f.ticker='IHSG' AND (p.ticker IS NULL OR abs(f.close-p.close::double precision)>1e-9)),
 'source_rows_covered',(SELECT SUM(frequency_source_rows) FROM public."Feature_06_Foreign_Domestic_INDEX" WHERE ticker='IHSG'),
 'legacy_ihsg_counts',jsonb_build_object('F01',(SELECT count(*) FROM public."Feature_01_Stock_Daily" WHERE ticker='IHSG'),
 'F02',(SELECT count(*) FROM public."Feature_02_Broker_Rolling" WHERE ticker='IHSG'),
 'F03',(SELECT count(*) FROM public."Feature_03_Stock_Broker_Daily" WHERE ticker='IHSG'),
 'F04',(SELECT count(*) FROM public."Feature_04_Technical_Indicator" WHERE ticker='IHSG'),
 'F05',(SELECT count(*) FROM public."Feature_05_Foreign_Domestic_Broker_Detail" WHERE ticker='IHSG'),
 'F06',(SELECT count(*) FROM public."Feature_06_Foreign_Domestic" WHERE ticker='IHSG')));
